INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(129293, 'ruRU', '', 'Этот взрыв мог быть даже лучше прошлого! Тетис бы одобрила.', 24330),
(129298, 'ruRU', '', 'Нашим разбойникам не помешала бы помощь в выполнении задания в этой пещере. Эти шумовые бомбы дадут им именно то преимущество, что нужно!', 24330),
(129299, 'ruRU', '', 'Потрясающая работа! Или "оглушительная" было бы точнее?', 24330),
(129301, 'ruRU', '', 'Верная подруга, что отдала жизнь, защищая этот храм. Её покой был осквернён, и теперь она бродит по этим залам как банши. Освободи её от этих мучений!', 24330),
(129303, 'ruRU', '', 'Покой, заслуженный ею так давно, был возвращён ей. Прими мою благодарность.', 24330),
(129304, 'ruRU', '', 'В жизни Риул был грозным воином. В смерти он - мерзость, обращённая против нас. Верни его в могилу.', 24330),
(129305, 'ruRU', '', 'Отлично сражался! Теперь Риул точно останется в своей могиле.', 24330),
(129323, 'ruRU', '', 'Снова демонический заговор против Древних! Покажи этим уродам, что с природой шутки плохи!', 24330),
(129324, 'ruRU', '', 'Глупые демоны. Они так никогда и не научатся, да? Им нас не победить!', 24330),
(129326, 'ruRU', '', 'Наши силы вступили в бой с Легионом на первом этаже. Нам нужно установить Эгиду в башне, прежде чем наши потери станут непреодолимыми.', 24330),
(129328, 'ruRU', '', 'Легион планирует атаки на наших Древних из этого лагеря. Помоги нам разрушить их планы!', 24330),
(129329, 'ruRU', '', 'Это должно остановить их планы, по крайней мере на время. Спасибо за помощь!', 24330),
(129331, 'ruRU', '', 'Эти метки выглядят свежими. Постарайся держаться в стороне, пока мы с этим не разберёмся, $n. Не хотелось бы, чтобы ты пострадал.', 24330),
(129332, 'ruRU', '', 'Даумир ждёт тебя, Повелитель смерти. Не хочешь обрушить немного разрушения?', 24330),
(129334, 'ruRU', '', 'Чудесно!', 24330),
(129335, 'ruRU', '', 'Не подходи слишком близко, $n. Эту область недавно атаковали. Здесь небезопасно.', 24330),
(129336, 'ruRU', '', 'Совет попросил меня изучить эти свежие следы ожогов. Похоже, они совсем недавние.', 24330),
(129339, 'ruRU', '', 'Наши рыцари смерти выпустили армию драконов-нежити бомбардировать эту область. Не хочешь присоединиться к веселью?', 24330),
(129340, 'ruRU', '', 'Прости, если мой клинок найдёт твоё сердце, Иллидан. Когда вокруг столько демонов, трудно отличить тебя от остальной этой нечисти.', 24330),
(129341, 'ruRU', '', 'Ах, холодные объятия смерти. Так освобождает!', 24330),
(129344, 'ruRU', '', 'Наши союзники утверждают, что оснастили свой корабль разрушительным вооружением. Испытай их оружие в деле!', 24330),
(129345, 'ruRU', '', 'Такое неизящное оружие не заменит отточенный клинок, но, полагаю, оно было эффективным.', 24330),
(129348, 'ruRU', '', 'Неужели? Хранитель!', 24330),
(129349, 'ruRU', '', 'В давние века этот щит защищал юную душу мира от безумия и порчи. Сегодня он служит тем, кто сражается за Азерот.', 24330),
(129350, 'ruRU', '', 'Я Эгвин, Хранительница Тирисфаля. Я оставила это эхо своей силы как защиту на случай, если обереги, установленные мной для охраны гробницы, подведут. И действительно, я чувствую, что повелитель Пылающего Легиона теперь замышляет заполучить свою награду.', 24330),
(129351, 'ruRU', '', 'И всё же надежда ещё есть. Закрепив Столпы Созидания в залах внизу, вы восстановите мои обереги и отбросите захватчиков. Затем вам нужно отправиться в глубины гробницы и использовать Око Амантула, чтобы уничтожить Шторм Скверны и разорвать связь Легиона с Азеротом.', 24330),
(129353, 'ruRU', '', 'Но одни лишь Столпы не принесут победы. Лишь объединённая армия, основанная на силе и мужестве, может победить Легион. Когда вы и ваши союзники будете готовы к финальной битве, моё эхо вернётся, чтобы помочь вам. Судьба Азерота в ваших руках.', 24330),
(129354, 'ruRU', '', 'Кадгар захочет об этом услышать.', 24330),
(129397, 'ruRU', '', 'Пришёл помочь, $n? Я пока не смог поставить диагноз. Симптомы у всех совершенно разные.', 24330),
(129398, 'ruRU', '', 'Если у жителей продолжат проявляться эти симптомы, нам нужно начать обучать дополнительных помощников.', 24330),
(129402, 'ruRU', '', 'Пожалуйста, сохраняйте спокойствие. Мы поможем каждому из вас, но просим вашего терпения.', 24330),
(129403, 'ruRU', '', '$n! Они продолжают прибывать! Я никогда не видел ничего подобного.', 24330),
(129404, 'ruRU', '', 'Если здесь слишком людно, пожалуйста, выйдите наружу. У нас установлены дополнительные пункты, и там готов помочь ассистент.', 24330),
(129405, 'ruRU', '', 'Мы привлекли дополнительную помощь и скоро подойдём к вам. Пожалуйста, потерпите.', 24330),
(129406, 'ruRU', '', 'Не знаю, сколько ещё мы можем так продержаться, $n. У нас начинают заканчиваться припасы.', 24330),
(129407, 'ruRU', '', 'У нас заканчивается место для гостей. Не знаю, сколько ещё мы можем так продержаться.', 24330),
(129408, 'ruRU', '', 'Есть какие-нибудь новости, $n? Симптомы продолжают проявляться, но для этого совершенно нет объяснения!', 24330),
(129409, 'ruRU', '', 'Довольно скоро нам придётся отправлять людей за помощью в другое место. Я просто не думаю, что у нас здесь достаточно ресурсов, чтобы поддерживать хоть какой-то порядок.', 24330),
(129410, 'ruRU', '', 'Очень надеюсь, что это уляжется. Люди прибывают в панике.', 24330),
(129411, 'ruRU', '', 'Я никогда не видел ничего подобного раньше, $n. Мы будем продолжать стараться. Обязательно направляй к нам всех с похожими симптомами.', 24330);
